/**
 * @summary Send admin reply to a user
 */
export const getSendAdminChatReplyUrl = (userId: number) => {
  return `/api/chat/admin/reply/${userId}`;
};

export const sendAdminChatReply = async (
  userId: number,
  sendAdminChatReplyBody: SendAdminChatReplyBody,
  options?: RequestInit,
): Promise<ChatMessage> => {
  return customFetch<ChatMessage>(getSendAdminChatReplyUrl(userId), {
    ...options,
    method: "POST",
    headers: { "Content-Type": "application/json", ...options?.headers },
    body: JSON.stringify(sendAdminChatReplyBody),
  });
};

